css:
.d-dual-list-transfer{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-dual-list-transfer *,.d-dual-list-transfer *::before,.d-dual-list-transfer *::after{box-sizing:border-box}
.d-dual-list-transfer [hidden]{display:none!important}
.d-dual-list-transfer .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-dual-list-transfer .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-dual-list-transfer label{display:block;margin:8px 0}
.d-dual-list-transfer input,.d-dual-list-transfer select,.d-dual-list-transfer textarea,.d-dual-list-transfer button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-dual-list-transfer input:not([type=checkbox]):not([type=radio]),.d-dual-list-transfer select,.d-dual-list-transfer textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-dual-list-transfer button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-dual-list-transfer button:disabled{opacity:.5;cursor:default}
.d-dual-list-transfer :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-dual-list-transfer [aria-invalid=true]{border-color:var(--warn)!important}
.d-dual-list-transfer .d-scroll{max-width:100%;overflow:auto}
.d-dual-list-transfer table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-dual-list-transfer th,.d-dual-list-transfer td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-dual-list-transfer caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-dual-list-transfer progress{width:100%;accent-color:var(--ink)}
.d-dual-list-transfer pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-dual-list-transfer h3,.d-dual-list-transfer p{margin:8px 0}
.d-dual-list-transfer [aria-pressed=true],.d-dual-list-transfer [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-dual-list-transfer .d-grow{flex:1;min-width:100px}
.d-dual-list-transfer summary{cursor:pointer;padding:6px 0}
.d-dual-list-transfer ul,.d-dual-list-transfer ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const left=q('[data-available]'),right=q('[data-chosen]');const sync=()=>{q('[data-in]').disabled=!left.selectedOptions.length;q('[data-outward]').disabled=!right.selectedOptions.length;};const move=(from,to)=>{const chosen=[...from.selectedOptions];chosen.forEach(option=>{option.selected=false;to.append(option);});sync();say('已移动 '+chosen.length+' 项；已选共 '+right.options.length+' 项');};left.onchange=right.onchange=sync;q('[data-in]').onclick=()=>move(left,right);q('[data-outward]').onclick=()=>move(right,left);sync();})(root, q, qa, say);
}
